from collections import deque

def find_hollow_rectangles(grid):
    """Find hollow rectangles by finding connected component bounding boxes"""
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    rectangles = []

    def get_component_bounds(start_r, start_c, val):
        """Get bounds of connected component with value val"""
        bounds = {'min_r': start_r, 'max_r': start_r, 'min_c': start_c, 'max_c': start_c}
        q = deque([(start_r, start_c)])
        visited[start_r][start_c] = True

        while q:
            r, c = q.popleft()
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == val:
                    visited[nr][nc] = True
                    q.append((nr, nc))
                    bounds['max_r'] = max(bounds['max_r'], nr)
                    bounds['max_c'] = max(bounds['max_c'], nc)

        return bounds

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                val = grid[r][c]
                bounds = get_component_bounds(r, c, val)
                rectangles.append(bounds)

    return rectangles

